"""Render the final gate matrix from retained terminal receipts only."""
import pathlib,json,collections
E=pathlib.Path(__file__).resolve().parent;Q=json.loads((E/'qualification.json').read_text());by={r['suite']:r for r in Q['rows']};M=json.loads((E/'source.json').read_text());modes=['ordinary','wagodebug','wago_regalloccheck']
def verdict(n):return by.get(n,{}).get('verdict','NOT_RUN')
def group(ns):
 vs=[verdict(n) for n in ns]
 return 'PASS' if vs and all(v=='PASS' for v in vs) else 'FAIL' if 'FAIL' in vs else 'INTERRUPTED' if 'INTERRUPTED' in vs else 'NOT_RUN'
labels=[('Full root ./...','full-root-replay'),('Runtime-tagged CLI','cli'),('Installer nested module','installer'),('Bench nested module','nested'),('Full collector family','collector'),('Full collector/runtime/Wago/integration race','race'),('Reduced parent reference-store race','parent-race-reduced'),('Full runtime/Wago guard pages','guard'),('Canonical candidate corpus','corpus'),('Fresh matched baseline corpus','baseline-corpus'),('Explicit RFW catalog, no inline + lifetime analysis','catalog'),('Actual candidate GC graphs and scalar/noGC controls','graphs-port'),('Baseline GC graphs and controls','graphs-baseline'),('Official spec v1','spec-v1'),('Official spec v2','spec-v2'),('Official spec v3','spec-v3'),('Official spec v3 signals/guard pages','spec-v3-signals'),('Guard-page corpus','guard-corpus'),('Full backend','backend'),('Full default backend diagnostics + Wago','diagnostics-default'),('Full WAGO_SHARED_SCALAR=0 diagnostics + Wago','diagnostics-established'),('Root build','tooling-build'),('Root vet','tooling-vet'),('Runtime CLI build','runtime-cli-build'),('Profile metadata','profile-metadata'),('Profile runtime/unwind','profile-runtime'),('Explicit shared-scalar controls','shared-scalar'),('Native joins','native-join'),('Four seeded concurrency runs, 24 rounds each','seeded-concurrency'),('Actual TinyGo serial evacuation','tinygo-evacuation'),('Actual TinyGo joint/foreign-stack supplement','tinygo-joint'),('Actual TinyGo supported conversion compatibility','tinygo-conversion')]
lines=['# Immutable combined correctness qualification','',f"Source: `{M['pin']}`. Evidence commit: supplied in the final handoff; no later source head is qualified.",'','This is a correctness checkpoint, not final review, inclusion, PR readiness or performance qualification. Darwin has no established execution runner and remains NOT_RUN. The November 4 deadline does not waive that gap.','', '| Gate | Ordinary | wagodebug | wago_regalloccheck |','| --- | --- | --- | --- |']
effective=[]
for title,prefix in labels:
 ns=[prefix+'-'+m for m in modes];effective+=ns;lines.append('| '+title+' | '+' | '.join(verdict(n) for n in ns)+' |')
for title,prefix in [('Collector hardening, three repetitions','hardening'),('Host transitions, three repetitions','host-transition')]:
 for guard in [False,True]:
  ns=[prefix+'-'+((m if m!='ordinary' else '')+(',wago_guardpage' if guard else '')).strip(',') for m in modes];ns=[n if not n.endswith('-') else n+'ordinary' for n in ns];effective+=ns
  lines.append('| '+title+(' / guard pages' if guard else ' / explicit bounds')+' | '+' | '.join(verdict(n) for n in ns)+' |')
for arch in ['arm64','riscv64']:
 for lane in ['collector','facade','guest']:
  ns=['qemu-'+lane+'/'+arch+'-'+m+'-'+lane for m in modes];effective+=ns;lines.append('| Actual QEMU '+arch+' '+lane+' | '+' | '.join(verdict(n) for n in ns)+' |')
for lane,arch,title in [('qemu-h6','arm64','Actual ARM64 H6 ownership/wakeup adapter'),('qemu-rv64-controls','riscv64','Actual full RV64 managed-function controls')]:
 ns=[lane+'/'+arch+'-'+m+'-guest' for m in modes];effective+=ns;lines.append('| '+title+' | '+' | '.join(verdict(n) for n in ns)+' |')
lines+=['','| Repository / supplemental gate | Verdict |','| --- | --- |']
tooling=[('Generation','tooling-generate'),('Generated-file diff','replay-generated-diff'),('Formatting','replay-format'),('Docs','replay-docs'),('Actionlint','replay-actionlint'),('Staticcheck, all four reviewed profiles','replay-staticcheck'),('Native-compare recipe','replay-native-compare'),('Portable 386 package execution','tooling-portable-386'),('RISC-V CI script contracts','tooling-script-ci-riscv64')]
for n in ['update-website-bench','update-website-startup','engine-state-oracle','fuzz-engine-state']:tooling.append(('Node '+n,'tooling-node-'+n))
for n in ['build-release-assets.sh','release-qualification.sh','ci-download-go-modules.sh']:tooling.append((n,'replay-'+n))
for n in ['check-diagnostic-dce.sh','check-riscv64-diagnostics.sh','check-regalloc-code.sh']:tooling.append((n,'tooling-script-'+n))
for title,n in tooling:effective.append(n);lines.append('| '+title+' | '+verdict(n)+' |')
tiny=[r['suite'] for r in Q['rows'] if r['suite'].startswith('tinygo-34/')];effective+=tiny
lines.append('| Actual patched TinyGo 0.42 foreign-stack lane, all 34 commands | '+group(tiny)+' |')
fuzz=['FuzzStructCardDifferential','FuzzValidateRelativePathAndRustScannerDoNotPanic','FuzzNormalizeWABTJSONDoesNotPanic','FuzzSpecTrapMatchingDoesNotPanic','FuzzDecodeValidateByteBackedDifferentialGenerated']
for prefix,title in [('fuzz-','Configured bounded fuzz runs'),('fuzz-30s-','Extended 30-second bounded fuzz runs')]:
 ns=[prefix+n for n in fuzz];effective+=ns;lines.append('| '+title+' | '+group(ns)+' |')
lines.append('| Native Darwin execution | NOT_RUN |')
counts=collections.Counter(verdict(n) for n in effective)
lines+=['',f"Effective required command receipts (excluding Darwin): `{dict(counts)}`. `qualification.json` indexes every attempt and skip reason; per-command result JSON and raw logs retain the full terminal events, including recovered harness failures. Build-only target receipts are separate from actual execution receipts.",'','## Corpus and target boundaries','', '`corpus-per-id.json` contains all 768 ID/revision/mode rows; `corpus-joins.json` contains all 384 comparisons. `corpus-identity.json` verifies 128 IDs, 121 distinct binaries and 47 input references. `catalog-per-id.json` separately records the 384 explicit-RFW compile rows. The baseline is immutable `a3c08365f531eb3c9003e3acf3e0a822c12c31f4`; its canonical checked compile-only preflight runs before baseline execution. The known unsafe baseline no-inline/lifetime-analysis clang-cpp configuration is never executed and is not waived by canonical passes.','', '`reference-only-skips.json` enumerates captured external-runtime references; these are not fresh V8/wasmtime execution claims. Fresh supported wazero references and all Wago semantic/application contracts are accounted for separately. The historical corpus is not GC graph coverage: `generated-graph-identities.json` and separate graph gates retain the real guest graph, scalar and noGC controls. The graph oracle requires 32 live objects and at least 2,048 allocations after 64 calls and collection.','', '`spec-accounting.json` retains per-file and total modules/assertions/gaps for each explicitly configured official spec lane. Suite PASS never promotes an optional skipped test into execution. ARM64 QEMU executes supported H6/H2 host-container/import tests. RV64 controls qualify its supported compact representation; build-excluded opaque-host receipts are not passes. TinyGo compatibility likewise does not establish excluded host opaque receipt support. B’s pending worker handoff is not assumed or polled; all results here concern the frozen combined source.','', '## Retained harness failures','', 'The initial target census also detected that amd64-only H6 test tags excluded those bodies from the ARM64 command. Its failed census is retained. A new ARM64-only adapter preserves both H6 test bodies byte-for-byte and executes all nine ownership/wakeup families in all modes; the full RV64 managed-function family is separately executed. No excluded tests are promoted to passes. Three discovery failures were retained without changing source or expectations: the initial root run reached the mise PowerShell shim; initial native-compare reached the mise just shim; initial Staticcheck lacked its installed binary on PATH. Complete required replays use explicit PowerShell 7.6.8, just 1.58.0 and the verified Staticcheck directory. Their command/log receipts remain alongside the passing replays. Any additional failures or interruptions are authoritative in qualification.json, not silently omitted.','', '## Provenance and handoff','', '`source.json`, `source-ancestry.json`, source manifests, tool hashes and every command receipt pin provenance. Main tests use Go 1.27.1, Node 24.22.2, WABT 1.0.41 and the pinned Release 3 interpreter/OCaml environment. QEMU uses Go 1.27.3 and the recorded Debian emulator package SHA256. TinyGo is the actual patched 0.42 binary with a fresh cache. Shared submodules and expectations are untouched; private Git metadata supports repository scripts. Inherited orchestration metadata is omitted from committed command environments as recorded in environment-metadata-redactions.json; test/toolchain variables are retained.','', '`exports-integrity-after.json` compares original archived files after execution; declared baseline graph test overlays and target-only added adapters are separately documented. `drivers-integrity-after.json` checks the recorded driver hashes. `preservation-normalization.json` retains the initial status-comparison formatting mismatch and its normalized equality check. `cleanup.json` and `process-drain.json` record only owned export/cache cleanup and process readiness. Read those receipts before independent measurement scheduling; this report grants no measurement lease.','', 'Only this evidence directory is committed. It is not consumed by shipped builds and cannot affect shipped performance. No production edits, benchmarks, performance timings, subagents, reviews, PRs, pushes or closures were performed. Test-framework durations in raw logs are incidental correctness output.','', 'Rebuild terminal summaries without executing tests: `python3 docs/rfwgc-evidence/final-combined-f2bb/report.py`, then `accounting.py`, then `render-report.py` in the same directory.']
(E/'README.md').write_text('\n'.join(lines)+'\n');(E/'effective-gates.json').write_text(json.dumps(dict(source=M['pin'],rows=[dict(suite=n,verdict=verdict(n)) for n in effective],counts=dict(counts),Darwin='NOT_RUN'),indent=2)+'\n')
